func encRequest(out []byte, v *Request, depth int) []byte {
	out = append(out, '{')
	out = append(out, '\n')
	out = pad(out, depth+1)
	out = esc(out, "op")
	out = append(out, ':', ' ')
	out = esc(out, v.Op)
	if v.Name != "" {
		out = append(out, ',')
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "name")
		out = append(out, ':', ' ')
		out = esc(out, v.Name)
	}
	if len(v.Rights) != 0 {
		out = append(out, ',')
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "rights")
		out = append(out, ':', ' ')
		out = strs(out, v.Rights, depth+1)
	}
	if v.Secret != "" {
		out = append(out, ',')
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "secret")
		out = append(out, ':', ' ')
		out = esc(out, v.Secret)
	}
	if v.Token != "" {
		out = append(out, ',')
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "token")
		out = append(out, ':', ' ')
		out = esc(out, v.Token)
	}
	if v.Right != "" {
		out = append(out, ',')
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "right")
		out = append(out, ':', ' ')
		out = esc(out, v.Right)
	}
	if v.Why != "" {
		out = append(out, ',')
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "why")
		out = append(out, ':', ' ')
		out = esc(out, v.Why)
	}
	if v.App != "" {
		out = append(out, ',')
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "app")
		out = append(out, ':', ' ')
		out = esc(out, v.App)
	}
	if v.Admin != "" {
		out = append(out, ',')
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "admin")
		out = append(out, ':', ' ')
		out = esc(out, v.Admin)
	}
	out = append(out, '\n')
	out = pad(out, depth)
	return append(out, '}')
}

